Item.method_code:
//Increment Sequence Number参考

const prt =
	typeof parent.document.item === 'object' ? parent.document : parent.parent;
const currentItem = prt.item;
const newRelationships = currentItem.selectNodes(
	`Relationships/Item[@type="${relationshipTypeName}" and @isTemp="1"]`
);
if (!newRelationships || newRelationships.length < 2) {
	aras.getItemRelationshipsEx(currentItem, relationshipTypeName);
}

const xPathMaxSortOrder = `Relationships/Item[@type="${relationshipTypeName}"][not(../Item[@type="${relationshipTypeName}"]/sort_order > sort_order)]/sort_order`;
const maxSortOrderNode = currentItem.selectSingleNode(xPathMaxSortOrder);
const nextSortOrderValue = maxSortOrderNode
	? parseInt(maxSortOrderNode.textContent) + 128
	: 128;

const relationshipItem = currentItem.selectSingleNode(
	`Relationships/Item[@id="${relationshipID}"]`
);
aras.setItemProperty(relationshipItem, 'sort_order', nextSortOrderValue);
